create or replace function public.apply_new_class_basic_attack()returns trigger language plpgsql security definer set search_path=''as $$declare hero public.characters%rowtype;primary_stat integer;begin select*into hero from public.characters where id=new.character_id;if hero.character_class not in('barbarian','monk','sorcerer','warlock','artificer','necromancer')then return new;end if;primary_stat:=case hero.character_class when'barbarian'then hero.strength when'monk'then hero.dexterity when'sorcerer'then hero.charisma when'warlock'then hero.charisma else hero.intelligence end;new.base_damage:=greatest(2,2+hero.level+floor(primary_stat/4)::integer);new.damage_type:=case hero.character_class when'monk'then'bludgeoning'when'sorcerer'then'fire'when'warlock'then'psychic'when'artificer'then'lightning'when'necromancer'then'cold'else'slashing'end;return new;end;$$;
create trigger timed_combat_new_class_stats before insert on public.timed_combat_actions for each row execute function public.apply_new_class_basic_attack();
